from money import format_money

# Sales tax for the store's state. Accountants round tax half up, to the cent.
TAX_RATE = "0.0875"


class Invoice:
    def __init__(self):
        self.lines = []

    def add(self, description, unit_price, qty=1):
        """unit_price is a string in dollars and cents, e.g. "19.99"."""
        self.lines.append((description, float(unit_price), qty))

    def subtotal(self):
        return sum(price * qty for _, price, qty in self.lines)

    def tax(self):
        return round(self.subtotal() * float(TAX_RATE))

    def total(self):
        return self.subtotal() + self.tax()

    def summary(self):
        return {
            "subtotal": format_money(self.subtotal()),
            "tax": format_money(self.tax()),
            "total": format_money(self.total()),
        }

