import unittest

from invoice import Invoice


class Regression(unittest.TestCase):
    def test_half_a_cent_rounds_up(self):
        # 2.00 x 8.75% is exactly 0.175, which rounds half up to 0.18.
        inv = Invoice()
        inv.add("Sticker", "2.00")
        self.assertEqual(inv.summary()["tax"], "$0.18")
        self.assertEqual(inv.summary()["total"], "$2.18")

    def test_quantities_multiply(self):
        inv = Invoice()
        inv.add("Pen", "1.25", qty=4)
        self.assertEqual(inv.summary(), {"subtotal": "$5.00", "tax": "$0.44", "total": "$5.44"})

    def test_many_small_lines_add_up_exactly(self):
        inv = Invoice()
        for _ in range(3):
            inv.add("Postcard", "0.10")
        self.assertEqual(inv.subtotal() * 100, 30)

    def test_an_empty_invoice_is_zero(self):
        self.assertEqual(Invoice().summary(), {"subtotal": "$0.00", "tax": "$0.00", "total": "$0.00"})

